const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = [
  { id: 'js', title: '자바스크립트 입문', hours: 12, badge: '신규', tutor: '김강사' },
  { id: 'react', title: '리액트 시작하기', hours: 20, badge: '인기', tutor: '이강사' },
];

// 한 덩어리로 적었습니다. 아직 아무것도 나누지 않았습니다.
const Course = ({ title, hours, badge, tutor }) => (
  <article className="course">
    <div className="course__head">
      <h3 className="course__title">{title}</h3>
      <span className="badge">{badge}</span>
    </div>
    <p className="course__meta">{hours}시간</p>
    <p className="course__tutor">
      <span className="course__tutor-face" />
      {tutor}
    </p>
  </article>
);

root.render(
  <>
    {courses.map((course) => (
      <Course
        key={course.id}
        title={course.title}
        hours={course.hours}
        badge={course.badge}
        tutor={course.tutor}
      />
    ))}
  </>
);

